====ACCOUNT LIST====
查询账号列表

Usage:
  ziniao-cli account list [flags]

Flags:
      --format string    输出格式: json|table|csv (default "json")
  -h, --help             help for list
  -q, --jq string        jq 过滤表达式
      --name string      按名称搜索
      --page-all         自动翻页（默认最多 10 页，配合 --page-limit 0 可取全部）
      --page-delay int   翻页间隔毫秒数（配合 --page-all） (default 200)
      --page-limit int   最大翻页数（默认 10，0 为不限，配合 --page-all） (default 10)
      --page-size int    每页条数 (default 20)
====VERSION====
ziniao-cli version 1.0.7
====CONFIG SHOW====
{
  "ok": true,
  "data": {
    "apiKey": "(stored in keychain)",
    "configPath": "C:\\Users\\Administrator\\.ziniao-cli\\config.json",
    "isBoss": false,
    "profile": "ZHANGSHUAI",
    "serverUrl": "https://sbappstoreapi.ziniao.com"
  }
}
====CONFIG LIST====
* ZHANGSHUAI
====ZCLAW TOOLS LIVE====
{
  "ok": true,
  "data": [
    {
      "description": "Resolve a Ziniao store by exact storeId or exact store name.",
      "name": "resolve_store"
    },
    {
      "description": "List available Ziniao stores.",
      "name": "list_stores"
    },
    {
      "description": "Open a Ziniao store browser by exact storeId or store name. Response may include downloadFolderPath (SDK persistence path: allowed download folder for that store). If Chrome kernel must be downloaded first, the client auto-downloads and retries; response may include kernelDownloading and zclawLaunchHint (typically 1-5 minutes).",
      "name": "open_store"
    },
    {
      "description": "Close a running Ziniao store browser.",
      "name": "close_store"
    },
    {
      "description": "Open or navigate a store page.",
      "name": "visit_page"
    },
    {
      "description": "Click a DOM element by CSS selector, OR use hint (visible text / aria-label fragment) when the user only describes a module or button—no selector required if hint is set; optional selector scopes search under that root.",
      "name": "click_element"
    },
    {
      "description": "Input text into a page element.",
      "name": "input_text"
    },
    {
      "description": "Read page content.",
      "name": "get_page_content"
    },
    {
      "description": "Query DOM elements.",
      "name": "query_elements"
    },
    {
      "description": "Scroll the page.",
      "name": "scroll_page"
    },
    {
      "description": "Capture screenshot.",
      "name": "take_screenshot"
    },
    {
      "description": "Wait for selector.",
      "name": "wait_for_element"
    },
    {
      "description": "Wait for navigation.",
      "name": "wait_for_navigation"
    },
    {
      "description": "mode=running: list stores; mode=store: launch status and downloadFolderPath when running; mode=page: content; mode=plugin: message.",
      "name": "extract_data"
    },
    {
      "description": "Run multi-step automation.",
      "name": "run_automation"
    },
    {
      "description": "Prepare agent resources.",
      "name": "prepare_agent"
    },
    {
      "description": "Read ZClaw logs.",
      "name": "get_logs"
    },
    {
      "description": "Save content to Downloads.",
      "name": "download_file"
    },
    {
      "description": "Execute JavaScript in page.",
      "name": "execute_script"
    },
    {
      "description": "Debug: compare account/list vs store/list response (id/store_id fields).",
      "name": "debug_compare_lists"
    }
  ],
  "meta": {
    "count": 20
  }
}
